let priceProduct='';
function priceMetric(label){const k=keyOf(label);if(k==='net sales price in kg')return 'price';if(k==='cost per kg')return 'cost';if(k==='net sales price'||k==='nps')return 'net';if(/^less\s*:\s*vat$/.test(k))return 'vat';if(/^sales\s/.test(k))return 'gross';return null;}
function convertPrice(raw){const c=raw.cells;if(clean(c.A1)!=='SBU Name'||clean(c.C1)!=='Product Name'||clean(c.D1)!=='Particulars')return null;const dates=[],seen=new Set();for(let j=4;j<300;j++){const date=c[col(j)+'1'];if(date===undefined)continue;const p=parsePeriod(date);if(typeof date!=='number'||!Number.isFinite(date)||!p)throw Error('Net Sales Price requires monthly Excel dates on row 1.');const key=p.year+'-'+p.month;if(seen.has(key))throw Error('Duplicate Net Sales Price month.');seen.add(key);dates.push({column:col(j),...p});}if(!dates.length)throw Error('No Net Sales Price reporting months found.');const groups=new Map();for(let r=2;r<=1000;r++){if(!clean(c['D'+r]))continue;const name=clean(c['A'+r]),code=clean(c['B'+r]),product=clean(c['C'+r]),metric=priceMetric(c['D'+r]);if(!name||!code||!product)throw Error('Net Sales Price row '+r+' requires SBU Name, SBU Code and Product Name.');if(!metric)throw Error('Unsupported pricing measure on row '+r+': '+c['D'+r]);const id=keyOf(code);if(!groups.has(id))groups.set(id,{name,code,rows:[],used:new Set()});const g=groups.get(id);if(keyOf(g.name)!==keyOf(name))throw Error('Conflicting SBU names for '+code);const unique=productKey(product)+'|'+metric;if(g.used.has(unique))throw Error('Duplicate product pricing measure: '+product);g.used.add(unique);g.rows.push(r);for(const d of dates){const v=c[d.column+r];if(v!==undefined&&v!==null&&v!==''&&(typeof v!=='number'||!Number.isFinite(v)))throw Error('Pricing value must be numeric or blank at '+d.column+r);}}
return [...groups.values()].map(g=>{const cells={};for(const [a,v] of Object.entries(c))if(+a.match(/\d+/)[0]===1||g.rows.includes(+a.match(/\d+/)[0]))cells[a]=v;const existing=Object.values(portfolio.sbus).find(s=>keyOf(s.code||s.books.income?.sbuCode)===keyOf(g.code));return {kind:'pricing',sbuName:existing?.name||g.name,book:{name:raw.name,sheet:raw.sheet,cells,sbuCode:g.code,layout:'net-sales-price-v1'}};});}
function pricingBook(){return portfolio.sbus[activeSbu]?.books.pricing;}
function priceDefinitions(){const c=pricingBook()?.cells||{},map=new Map();for(let r=2;r<=1000;r++){const name=clean(c['C'+r]),metric=priceMetric(c['D'+r]);if(!name||!metric)continue;const key=productKey(name);if(!map.has(key))map.set(key,{key,name,rows:{}});map.get(key).rows[metric]=r;}return [...map.values()];}
function priceValue(p,metric,month=ids().at(-1),year=+state.year){const c=pricingBook()?.cells||{};for(let j=4;j<300;j++){const date=parsePeriod(c[col(j)+'1']);if(date?.year===year&&date.month===month){const address=col(j)+p.rows[metric],v=c[address];return {value:typeof v==='number'&&Number.isFinite(v)?v:null,cell:p.rows[metric]===undefined?null:address};}}return {value:null,cell:null};}
function priceSnapshot(p,month=ids().at(-1)){const v={};for(const key of ['gross','vat','net','price','cost'])v[key]=priceValue(p,key,month).value;v.spread=sub(v.price,v.cost);v.check=v.gross===null||v.vat===null||v.net===null?null:v.gross-v.vat-v.net;return v;}
function pricingTrend(p){const c=pricingBook()?.cells||{},ms=[];for(let j=4;j<300;j++){const d=parsePeriod(c[col(j)+'1']);if(d?.year===+state.year)ms.push(d.month);}const points=ms.map(m=>({month:m,...priceSnapshot(p,m)})),vals=points.flatMap(p=>[p.price,p.cost]).filter(Number.isFinite);if(!vals.length)return empty();const w=700,h=240,left=65,bottom=35,top=20,lo=Math.min(0,...vals),hi=Math.max(...vals,1),y=v=>top+(hi-v)/(hi-lo)*(h-top-bottom),x=i=>left+i*(w-left-20)/Math.max(ms.length-1,1);return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Supplied monthly net selling price and indicative cost per kg">${[0,.5,1].map(f=>`<text x="${left-6}" y="${y(lo+(hi-lo)*f)+4}" text-anchor="end" font-size="11">${num(lo+(hi-lo)*f,1)}</text>`).join('')}${[['price','#087f8c'],['cost','#bd4655']].map(([k,color])=>points.map((p,i)=>p[k]===null?'':`${i&&points[i-1][k]!==null?`<line x1="${x(i-1)}" y1="${y(points[i-1][k])}" x2="${x(i)}" y2="${y(p[k])}" stroke="${color}" stroke-width="2"/>`:''}<circle cx="${x(i)}" cy="${y(p[k])}" r="4" fill="${color}"><title>${months[p.month]} ${k}: ${num(p[k],3)} BDT/kg</title></circle>`).join('')).join('')}${ms.map((m,i)=>`<text x="${x(i)}" y="${h-10}" text-anchor="middle" font-size="10">${months[m]}</text>`).join('')}</svg><p class="source">Teal: supplied net selling price/kg · Red: supplied indicative cost/kg. Gaps indicate missing values.</p>`;}
function pricingView(){const defs=priceDefinitions();if(!defs.length)return panel('Net Sales Price','No pricing file supplied for this SBU.',empty());if(!defs.some(p=>p.key===priceProduct))priceProduct=defs[0].key;const selected=defs.find(p=>p.key===priceProduct),month=ids().at(-1),snapshots=defs.map(p=>({p,v:priceSnapshot(p)})),known=snapshots.filter(x=>x.v.spread!==null),label=months[month]+' '+state.year;return panel('Net sales price & indicative cost',esc(label)+' monthly snapshot from the Net Sales Price workbook. Rates are BDT/kg; amounts are '+unit()+'.',`<p>${state.period==='ytd'?'The final selected month is shown for pricing. Monthly rates are not summed or averaged into a YTD rate.':'Monthly source values are shown as supplied.'}</p>`+table(['Product','Gross sales','VAT','Net sales','Net selling price/kg','Indicative cost/kg','Spread/kg','Gross − VAT − net'],snapshots.map(({p,v},i)=>[`<button data-price-evidence="${i}">${esc(p.name)}</button>`,money(v.gross),money(v.vat),money(v.net),num(v.price,3),num(v.cost,3),`<span class="${v.spread===null?'':v.spread<0?'negative':'positive'}">${num(v.spread,3)}</span>`,money(v.check)]))+`<p class="source">${known.filter(x=>x.v.spread<0).length} negative spreads among ${known.length} products with both rates. Spread = supplied net selling price/kg − supplied cost/kg. This is an indicative screening measure, not product net profit. The cost allocation basis is not provided.</p>`)+panel('Pricing trend',esc(pricingBook().name)+' · '+esc(pricingBook().sheet),select('priceProduct','Pricing product',defs.map(p=>[p.key,p.name]),priceProduct)+pricingTrend(selected)+table(['Month','Net selling price/kg','Indicative cost/kg','Spread/kg'],[...new Set(Object.entries(pricingBook().cells).filter(([a])=>/^[A-Z]+1$/.test(a)).map(([,v])=>parsePeriod(v)).filter(d=>d?.year===+state.year).map(d=>d.month))].map(m=>{const v=priceSnapshot(selected,m);return [`<button data-price-month="${m}">${months[m]} ${state.year}</button>`,num(v.price,3),num(v.cost,3),num(v.spread,3)];})))+panel('Pricing source vs income statement',esc(label)+' · Matching product labels only. Differences are retained, not overwritten.',table(['Pricing product','Pricing gross sales','Income-statement gross sales','Difference'],defs.map(p=>{const match=productDefinitions().find(x=>x.key===p.key),source=priceValue(p,'gross').value,income=match?productMeasure(match,[month]).gross:null;return[esc(p.name),money(source),money(income),money(sub(source,income))];})));}
function showPriceEvidence(p,month=ids().at(-1)){const b=pricingBook();$('evidenceBody').innerHTML=`<h2>${esc(p.name)} · ${months[month]} ${state.year}</h2><p class="source">${esc(b.name)} · ${esc(b.sheet)}</p><p>Monthly source values. Spread = net selling price/kg − cost/kg. No rates are inferred from the P&amp;L.</p>${table(['Measure','Source cell','Raw value','Unit'],Object.keys(p.rows).map(k=>{const v=priceValue(p,k,month);return[esc(k),v.cell||'—',num(v.value,4),['price','cost'].includes(k)?'BDT/kg':'BDT'];}))}`;$('evidence').showModal();}
const originalProductEconomics=products;products=function(){return pricingView()+originalProductEconomics();};
const priceBind=bind;bind=function(){priceBind();if(state.view!=='products')return;if($('priceProduct'))$('priceProduct').onchange=e=>{priceProduct=e.target.value;render();};document.querySelectorAll('[data-price-evidence]').forEach(e=>e.onclick=()=>showPriceEvidence(priceDefinitions()[+e.dataset.priceEvidence]));document.querySelectorAll('[data-price-month]').forEach(e=>e.onclick=()=>showPriceEvidence(priceDefinitions().find(p=>p.key===priceProduct),+e.dataset.priceMonth));const previousExport=$('export').onclick;$('export').onclick=()=>{if(!pricingBook())return previousExport();const rows=[['SBU',portfolio.sbus[activeSbu].name],['Pricing snapshot',months[ids().at(-1)]+' '+state.year],['Source file',pricingBook().name],['Product','Gross BDT','VAT BDT','Net BDT','Price BDT/kg','Cost BDT/kg','Spread BDT/kg'],...priceDefinitions().map(p=>{const v=priceSnapshot(p);return[p.name,v.gross,v.vat,v.net,v.price,v.cost,v.spread];}),[],['Income-statement product economics',period()],['Product','Gross BDT','VAT BDT','After VAT BDT','Sales MT','Production MT','Selling BDT/kg','Comparison gross BDT'],...currentProducts.map(p=>[p.name,p.a.gross,p.a.vat,p.a.net,p.a.volume,p.a.production,p.a.selling,p.b.gross])],u=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')],{type:'text/csv'})),a=document.createElement('a');a.href=u;a.download='Net_Sales_Price_'+state.year+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};};
